class AchievementSystem{constructor(){this.sessionMemes=0;this.totalViewed=this.loadTotalViewed();this.achievements=this.loadAchievements();this.init();}init(){this.trackMemeView();this.checkMilestones();}trackMemeView(){this.sessionMemes++;this.totalViewed++;this.saveTotalViewed();this.checkMilestones();}checkMilestones(){const milestones=[{key:'session_5',count:5,type:'session',title:'🔥 On Fire!',message:"5 memes in this session"},{key:'session_10',count:10,type:'session',title:'⚡ Power User!',message:"10 memes in one session!"},{key:'session_25',count:25,type:'session',title:'🚀 Unstoppable!',message:"25 memes! You're on a roll!"},{key:'session_50',count:50,type:'session',title:'🏆 Legend Status!',message:"50 memes in one session!"},{key:'total_10',count:10,type:'total',title:'👀 Getting Started!',message:"10 total memes viewed"},{key:'total_50',count:50,type:'total',title:'🎯 Meme Explorer!',message:"50 memes explored"},{key:'total_100',count:100,type:'total',title:'💯 Century Club!',message:"100 memes discovered!"},{key:'total_250',count:250,type:'total',title:'⭐ Meme Connoisseur!',message:"250 memes enjoyed"},{key:'total_500',count:500,type:'total',title:'👑 Meme Royalty!',message:"500 memes and counting!"},{key:'total_1000',count:1000,type:'total',title:'🌟 Meme Master!',message:"1,000 memes! Legendary!"},];milestones.forEach(milestone=>{const count=milestone.type==='session' ? this.sessionMemes:this.totalViewed;if(count===milestone.count && !this.achievements[milestone.key]){this.unlockAchievement(milestone);}});}unlockAchievement(milestone){this.achievements[milestone.key]=true;this.saveAchievements();this.showAchievementPopup(milestone);this.playAchievementSound();}showAchievementPopup(milestone){return;}playAchievementSound(){if(navigator.vibrate){navigator.vibrate([50,30,50]);}}loadTotalViewed(){return parseInt(localStorage.getItem('meme_total_viewed')|| '0',10);}saveTotalViewed(){localStorage.setItem('meme_total_viewed',this.totalViewed.toString());}loadAchievements(){const stored=localStorage.getItem('meme_achievements');return stored ? JSON.parse(stored):{};}saveAchievements(){localStorage.setItem('meme_achievements',JSON.stringify(this.achievements));}static trackView(){if(!window.achievementSystem){window.achievementSystem=new AchievementSystem();}else{window.achievementSystem.trackMemeView();}}static getStats(){if(!window.achievementSystem){window.achievementSystem=new AchievementSystem();}return{sessionMemes:window.achievementSystem.sessionMemes,totalViewed:window.achievementSystem.totalViewed,achievements:Object.keys(window.achievementSystem.achievements).length};}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{window.achievementSystem=new AchievementSystem();});}else{window.achievementSystem=new AchievementSystem();}window.AchievementSystem=AchievementSystem;